import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1 # Assuming positive integers, LCM of empty set is often defined as 1 for multiplicative identities
    return reduce(lcm, numbers)

sequence = [1, 2, 3, 6, 12, 18, 36, 72, 108, 144]
n = len(sequence)
good_partitions_count = 0

for k in range(1, n):
    A_k = sequence[:k]
    B_k = sequence[k:]

    L_k = list_lcm(A_k)
    G_k = list_gcd(B_k)

    if L_k == G_k:
        good_partitions_count += 1

print(f"The sequence has {good_partitions_count} good partitions.")

